"""Rebuild every generated file of the fictional example portfolio.

Usage (from the repository root):

    python -m scoring.build_examples           # write the files
    python -m scoring.build_examples --check   # fail if a committed file is out of date

For each use case in examples/use_cases.csv, the folder that holds its
``triage.yaml`` also holds:

- ``intake.md``                  written by hand (the completed intake form);
- ``triage.yaml``                triage answers, written by hand;
- ``business_case_inputs.yaml``  business case inputs, written by hand;
- ``decision.yaml``              the first decision and its reviews, written by hand;
- ``decision_2.yaml`` ...        later decisions on the same case (optional);
- ``triage.md``                  generated by scoring/triage.py;
- ``business_case.md``           generated by scoring/business_case.py;
- ``decision_record.md``,
  ``decision_record_2.md`` ...   generated by scoring/decision.py.

The story is told as of ``as_of_date`` in examples/portfolio.yaml: every review
due by then must be recorded, and value tracking (data/value_tracking.csv)
must run from each go-live or pilot start to that month, or to the month the
case was stopped.

The portfolio outputs (outputs/ranking.*, outputs/value_feasibility_matrix.png,
outputs/sensitivity.md) come from scoring/score.py; outputs/decisions.csv
lists the current decision, status and review history of every case; the
charts (outputs/portfolio_overview.png, cumulative_value.png, adoption.png)
come from dashboard/charts.py. This one command rebuilds everything.
"""

from __future__ import annotations

import argparse
import csv
import datetime as dt
import io
import re
import sys
from pathlib import Path

import yaml

from scoring import business_case as bc
from scoring import decision as dec
from scoring import score
from scoring.errors import InputError
from scoring.triage import load_checklist, to_markdown, triage_file

EXAMPLES_DIR = score.REPO_ROOT / "examples"
USE_CASES_CSV = EXAMPLES_DIR / "use_cases.csv"
PORTFOLIO_FILE = EXAMPLES_DIR / "portfolio.yaml"
TRACKING_FILE = score.REPO_ROOT / "data" / "value_tracking.csv"
HAND_WRITTEN = ("intake.md", "triage.yaml", "business_case_inputs.yaml", "decision.yaml")
DECISIONS_COLUMNS = ("id", "title", "short_title", "decision", "status", "decision_history", "ai_act_category",
                     "gate_result", "rank", "weighted_score", "quadrant", "npv_pessimistic_eur", "npv_base_eur",
                     "npv_optimistic_eur", "negative_scenario", "start_date", "review_gate_date", "gate_outcomes",
                     "other_reviews", "next_review", "stopped_on", "as_of")


def load_portfolio(path: Path = PORTFOLIO_FILE) -> dict:
    raw = yaml.safe_load(Path(path).read_text(encoding="utf-8")) or {}
    as_of = raw.get("as_of_date")
    if not isinstance(as_of, dt.date):
        raise InputError([f"{path}: 'as_of_date' must be a date (YYYY-MM-DD)."])
    return {"company": raw.get("company", ""), "as_of": as_of}


def decision_files(folder: Path) -> list[Path]:
    """decision.yaml, decision_2.yaml, decision_3.yaml ... in order."""
    files = []
    for p in folder.glob("decision*.yaml"):
        m = re.fullmatch(r"decision(?:_(\d+))?\.yaml", p.name)
        if m:
            files.append((int(m.group(1) or 1), p))
    numbers = [n for n, _ in sorted(files)]
    if numbers != list(range(1, len(numbers) + 1)):
        raise InputError([f"{folder.name}/: decision files must be numbered decision.yaml, decision_2.yaml, ..."])
    return [p for _, p in sorted(files)]


def record_name(decision_file: Path) -> str:
    m = re.fullmatch(r"decision(?:_(\d+))?\.yaml", decision_file.name)
    return "decision_record.md" if not m.group(1) else f"decision_record_{m.group(1)}.md"


def _with_fiction_note(markdown: str) -> str:
    """Insert the fictional-example note under the title of a generated file."""
    title, rest = markdown.split("\n", 1)
    return (f"{title}\n\n> **Fictional example.** \"Northwind Aero Services\" is a fictional MRO and spare-parts "
            f"company.\n{rest}")


def check_tracking(path: Path, table: list[dict], as_of: dt.date) -> None:
    """Value tracking covers each started case from its start month to the as-of (or stop) month."""
    import pandas as pd

    df = pd.read_csv(path, dtype=str, keep_default_na=False)
    months = {uc: sorted(g["month"]) for uc, g in df.groupby("use_case_id")}
    errors = []
    for row in table:
        uc = row["id"]
        if uc not in months:
            continue
        start = dt.date.fromisoformat(row["start_date"]).replace(day=1)
        end_day = dt.date.fromisoformat(row["stopped_on"]) if row["stopped_on"] else as_of
        end = end_day.replace(day=1)
        expected, day = [], start
        while day <= end:
            expected.append(day.isoformat())
            day = dec.add_months(day, 1)
        if months[uc] != expected:
            errors.append(f"{path}: {uc} must have one row per month from {expected[0]} to {expected[-1]} "
                          f"(start to {'stop' if row['stopped_on'] else 'as-of'} month); found "
                          f"{months[uc][0]} to {months[uc][-1]} ({len(months[uc])} rows).")
    started = [r["id"] for r in table
               if r["start_date"] and r["start_date"] <= as_of.isoformat() and r["status"] != "park"]
    missing = [uc for uc in started if uc not in months]
    if missing:
        errors.append(f"{path}: no value tracking for started use case(s): {', '.join(missing)}.")
    unknown = sorted(set(months) - {r["id"] for r in table})
    if unknown:
        errors.append(f"{path}: unknown use case(s): {', '.join(unknown)}.")
    if errors:
        raise InputError(errors)


def generate(csv_path: Path = USE_CASES_CSV, portfolio_path: Path = PORTFOLIO_FILE,
             tracking_path: Path | None = TRACKING_FILE) -> tuple[dict[Path, str], list[dict]]:
    """Return {path: text} for every generated example file, and the decisions table."""
    as_of = load_portfolio(portfolio_path)["as_of"]
    criteria = score.load_criteria()
    df = score.load_use_cases(csv_path, criteria)
    ranked = score.score_use_cases(df, criteria)
    checklist = load_checklist()
    files: dict[Path, str] = {}
    table: list[dict] = []
    errors: list[str] = []
    for _, row in df.iterrows():
        folder = (csv_path.parent / row[score.TRIAGE_FIELD]).parent
        missing = [name for name in HAND_WRITTEN if not (folder / name).is_file()]
        if missing:
            errors.append(f"{row['id']}: missing {', '.join(missing)} in {folder.name}/.")
            continue
        ranked_row = ranked[ranked["id"] == row["id"]].iloc[0].to_dict()
        if ranked_row["rank"] is not None and str(ranked_row["rank"]) == "<NA>":
            ranked_row["rank"] = None
        try:
            tri = triage_file(folder / "triage.yaml", checklist)
            case = bc.load_inputs(folder / "business_case_inputs.yaml")
            results = bc.compute_all(case)
            paths = decision_files(folder)
            decisions = [dec.load_decision(p) for p in paths]
            ids = [(p.name, d["use_case_id"]) for p, d in zip(paths, decisions)]
            ids += [("business_case_inputs.yaml", case.use_case_id), ("triage.yaml", tri.use_case_id)]
            for name, value in ids:
                if value != row["id"]:
                    errors.append(f"{folder.name}/{name}: use_case_id is '{value}', expected '{row['id']}'.")
            for a, b in zip(decisions, decisions[1:]):
                if b["decision_date"] <= a["decision_date"]:
                    errors.append(f"{folder.name}/: decision files must have increasing decision dates.")
            assessed = [dec.assess(d, ranked_row, case, results) for d in decisions]
            dec.check_as_of(decisions, [a["history"] for a in assessed], as_of)
            files[folder / "triage.md"] = _with_fiction_note(to_markdown(tri))
            files[folder / "business_case.md"] = bc.render_markdown(case, results)
            links = [{"file": record_name(p), "decision": d["decision"], "date": d["decision_date"]}
                     for p, d in zip(paths, decisions)]
            for i, (p, d) in enumerate(zip(paths, decisions)):
                files[folder / record_name(p)] = dec.render_decision_record(
                    d, ranked_row, len(ranked), criteria, tri, case, results, as_of=as_of,
                    previous=links[i - 1] if i else None,
                    superseded_by=links[i + 1] if i + 1 < len(links) else None)
        except InputError as exc:
            errors += exc.errors
            continue
        current, current_a = decisions[-1], assessed[-1]
        history = current_a["history"]
        gate_day = dec.gate_date(current) if current_a["gated"] else None
        gates = [g for a, d in zip(assessed, decisions) for g in [dec.gate_status(d, a["evaluated"])] if g]
        others = [s for d in decisions for s in [dec.review_log_status(d)] if s]
        table.append({
            "id": row["id"],
            "title": row["title"],
            "short_title": row.get("short_title", ""),
            "decision": current["decision"],
            "status": dec.portfolio_status(current, history),
            "decision_history": " -> ".join(f"{d['decision']} ({d['decision_date'].isoformat()})"
                                            for d in decisions),
            "ai_act_category": tri.category,
            "gate_result": ranked_row["gate_result"],
            "rank": "" if ranked_row["rank"] is None else int(ranked_row["rank"]),
            "weighted_score": f"{ranked_row['weighted_score']:.1f}",
            "quadrant": ranked_row["quadrant"],
            "npv_pessimistic_eur": round(results["pessimistic"]["npv_3y"]),
            "npv_base_eur": round(results["base"]["npv_3y"]),
            "npv_optimistic_eur": round(results["optimistic"]["npv_3y"]),
            "negative_scenario": "yes" if current_a["downside"]["negative_scenarios"] else "no",
            "start_date": decisions[0]["start_date"].isoformat() if decisions[0].get("start_date") else "",
            "review_gate_date": gate_day.isoformat() if gate_day else "",
            "gate_outcomes": ", ".join(gates),
            "other_reviews": ", ".join(others),
            "next_review": history["next_due"].isoformat() if history["next_due"] else "",
            "stopped_on": history["stopped_on"].isoformat() if history["stopped_on"] else "",
            "as_of": as_of.isoformat(),
        })
    if errors:
        raise InputError(errors)
    if tracking_path is not None:
        check_tracking(tracking_path, table, as_of)
    return files, table


def decisions_csv(table: list[dict]) -> str:
    buffer = io.StringIO()
    writer = csv.DictWriter(buffer, fieldnames=DECISIONS_COLUMNS, lineterminator="\n")
    writer.writeheader()
    writer.writerows(table)
    return buffer.getvalue()


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="python -m scoring.build_examples",
                                     description="Rebuild the generated files of the example portfolio.")
    parser.add_argument("--check", action="store_true",
                        help="Do not write; exit 1 if a generated file differs from the committed one.")
    parser.add_argument("--output-dir", type=Path, default=score.DEFAULT_OUTPUT_DIR)
    args = parser.parse_args(argv)
    try:
        files, table = generate()
    except InputError as exc:
        print("Input error:", file=sys.stderr)
        for message in exc.errors:
            print(f"  - {message}", file=sys.stderr)
        return 2
    files[args.output_dir / "decisions.csv"] = decisions_csv(table)

    if args.check:
        stale = [p for p, text in files.items()
                 if not p.is_file() or p.read_text(encoding="utf-8") != text]
        for p in stale:
            print(f"Out of date: {score._display_path(p)}", file=sys.stderr)
        if stale:
            print("Run: python -m scoring.build_examples", file=sys.stderr)
        return 1 if stale else 0

    for path, text in files.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8", newline="\n")
    print(f"Wrote {len(files)} generated files.")
    code = score.main([str(USE_CASES_CSV), "--sensitivity", "--output-dir", str(args.output_dir),
                       "--decisions", str(args.output_dir / "decisions.csv")])
    if code:
        return code
    from dashboard import charts
    return charts.main(["--output-dir", str(args.output_dir)])


if __name__ == "__main__":
    sys.exit(main())
